$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'import-backup.ps1')
$taskOut=Join-Path 'F:\Agentopia-Acceptance\recovery-preflight' ([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds().ToString());New-Item -ItemType Directory -Path $taskOut|Out-Null
$taskChecks=[Collections.Generic.List[string]]::new()
function New-RecoveryCase([string]$Name){$taskCaseHome=Join-Path $taskOut $Name;$data=Join-Path $taskCaseHome 'AppData\Roaming';New-Item -ItemType Directory -Path $data|Out-Null;return @{home=$taskCaseHome;data=$data}}
function Assert-RecoveryRefused([scriptblock]$Action,[string]$Pattern,[string]$Label){$failed=$false;try{& $Action|Out-Null}catch{if($_.Exception.Message -notmatch $Pattern){throw};$failed=$true};if(-not $failed){throw "Expected recovery refusal: $Label"};$taskChecks.Add($Label)}
$case=New-RecoveryCase 'fresh';$target=Get-AgentopiaRecoveryDestination $case.home $case.data @('Ubuntu');if($target -ne (Join-Path $case.data 'Agentopia\migration-input') -or (Test-Path -LiteralPath $target)){throw 'Fresh scope discovery wrote or selected another destination'};$taskChecks.Add('Fresh scope resolves without writes and leaves unrelated WSL distributions available.')
foreach($runtime in @('AgentopiaRuntime',"`tAgentopiaRuntime-11111111-1111-4111-8111-111111111111 `r",'agentopiaruntime-other-owned-name')){Assert-RecoveryRefused {Get-AgentopiaRecoveryDestination $case.home $case.data @('Ubuntu',$runtime)} 'existing Agentopia runtime' ('Existing runtime refused: '+$runtime.Trim())}
foreach($name in @('profile-location.json','migration.lock','profile')){$case=New-RecoveryCase ('private-'+$taskChecks.Count);$private=Join-Path $case.home '.agentopia\desktop';New-Item -ItemType Directory -Path $private|Out-Null;if($name -eq 'profile'){New-Item -ItemType Directory -Path (Join-Path $private $name)|Out-Null}else{[IO.File]::WriteAllText((Join-Path $private $name),'generated')};Assert-RecoveryRefused {Get-AgentopiaRecoveryDestination $case.home $case.data @()} 'private Agentopia profile' ('Existing private state refused: '+$name)}
foreach($name in @('migration-complete.json','migration-input','runtime-binding.json','credentials.bin')){$case=New-RecoveryCase ('legacy-'+$taskChecks.Count);$profile=Join-Path $case.data 'Agentopia';New-Item -ItemType Directory -Path $profile|Out-Null;if($name -eq 'migration-input'){New-Item -ItemType Directory -Path (Join-Path $profile $name)|Out-Null}else{[IO.File]::WriteAllText((Join-Path $profile $name),'generated')};Assert-RecoveryRefused {Get-AgentopiaRecoveryDestination $case.home $case.data @()} 'Existing Agentopia profile' ('Existing ordinary state refused: '+$name)}
$case=New-RecoveryCase 'redirect';$redirect=Join-Path $taskOut 'redirect-destination';New-Item -ItemType Directory -Path $redirect|Out-Null;$link=Join-Path $case.home 'AppData\LinkedRoaming';New-Item -ItemType Junction -Path $link -Value $redirect|Out-Null;Assert-RecoveryRefused {Get-AgentopiaRecoveryDestination $case.home $link @()} 'redirected or invalid' 'A redirected destination is refused before writing.'
$backup=Join-Path $taskOut 'generated-backup';New-Item -ItemType Directory -Path $backup|Out-Null;$entries=@()
foreach($name in @('auth.dump','application.dump','vault.dump','pgsodium_root.key','database.dump')){$file=Join-Path $backup $name;[IO.File]::WriteAllText($file,'GENERATED-'+$name);$entries+=@{name=$name;sha256=Get-AgentopiaRecoveryHash $file}}
function Save-RecoveryManifest($Files,$Format=1){@{format=$Format;files=$Files}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding utf8}
Save-RecoveryManifest $entries;$manifest=Read-AgentopiaRecoveryManifest $backup;if(@($manifest.files).Count -ne 5){throw 'Valid complete manifest refused'};$taskChecks.Add('All required and optional resources are hashed with .NET and accepted without Get-FileHash.')
$incomplete=Join-Path $backup 'BACKUP-INCOMPLETE.txt';[IO.File]::WriteAllText($incomplete,'GENERATED INCOMPLETE');Assert-RecoveryRefused {Read-AgentopiaRecoveryManifest $backup} 'incomplete' 'An interrupted legacy or upgrade backup is refused before copying database files.';[IO.File]::Delete($incomplete)
[IO.File]::AppendAllText((Join-Path $backup 'database.dump'),'damaged');Assert-RecoveryRefused {Read-AgentopiaRecoveryManifest $backup} 'incomplete or changed' 'Corruption of an optional database archive is refused.';[IO.File]::WriteAllText((Join-Path $backup 'database.dump'),'GENERATED-database.dump')
Save-RecoveryManifest ($entries+@($entries[0]));Assert-RecoveryRefused {Read-AgentopiaRecoveryManifest $backup} 'duplicate' 'Duplicate archive names are refused.'
$unsafe=@($entries|ForEach-Object {@{name=$_.name;sha256=$_.sha256}});$unsafe[0].name='../outside.dump';Save-RecoveryManifest $unsafe;Assert-RecoveryRefused {Read-AgentopiaRecoveryManifest $backup} 'Invalid or duplicate' 'Traversal and unlisted resource names are refused.'
Save-RecoveryManifest @($entries|Where-Object {$_.name -ne 'pgsodium_root.key'});Assert-RecoveryRefused {Read-AgentopiaRecoveryManifest $backup} 'missing' 'A missing database encryption root is refused.'
Save-RecoveryManifest $entries 2;Assert-RecoveryRefused {Read-AgentopiaRecoveryManifest $backup} 'Unsupported' 'An unknown backup format is refused.'
$receipt=@{success=$true;at=[DateTime]::UtcNow.ToString('o');out=$taskOut;checks=@($taskChecks);groups=$taskChecks.Count;helperSha256=Get-AgentopiaRecoveryHash (Join-Path $PSScriptRoot 'import-backup.ps1');productionChanged=$false;providerRequests=0}
$receipt|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $taskOut 'evidence.json') -Encoding utf8
$receipt|ConvertTo-Json -Depth 6 -Compress
